<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$pdo=aep_database();$matters=$pdo->query('SELECT m.*,c.name client_name,COUNT(t.id) task_count FROM matters m JOIN clients c ON c.id=m.client_id LEFT JOIN tasks t ON t.matter_id=m.id GROUP BY m.id ORDER BY m.updated_at DESC')->fetchAll();$pageTitle='Matters | AEP';$activeNav='matters';require __DIR__.'/includes/header.php';?>
<div class="actions" style="justify-content:space-between"><div><h1>Matters</h1><p class="muted">Connected legal workspaces for each client.</p></div><a class="btn" href="matter_create.php">Create matter</a></div><div class="card" style="margin-top:18px"><?php if(!$matters):?><div class="empty">Ready to create your first matter.<br><br><a class="btn" href="matter_create.php">Create matter</a></div><?php else:?><table><thead><tr><th>Reference</th><th>Client</th><th>Practice area</th><th>Subject</th><th>Tasks</th><th>Status</th></tr></thead><tbody><?php foreach($matters as $matter):?><tr><td><a href="matter_view.php?id=<?php echo (int)$matter['id'];?>"><?php echo aep_h($matter['matter_reference']);?></a></td><td><?php echo aep_h($matter['client_name']);?></td><td><?php echo aep_h($matter['practice_area']);?></td><td><?php echo aep_h($matter['subject']);?></td><td><?php echo (int)$matter['task_count'];?></td><td><span class="badge"><?php echo aep_h($matter['status']);?></span></td></tr><?php endforeach;?></tbody></table><?php endif;?></div><?php require __DIR__.'/includes/footer.php';?>
